{
  "sop_id": "SOP-016",
  "title": "Expense Claims",
  "steps": [
    {
      "step_id": "S1",
      "name": "Open and assign ticket",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Check each line against policy limits for claimant's grade and expense category",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Match every line to a receipt",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Determine reimbursable amount",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S5",
      "name": "Submit claim for approval",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "A1",
      "name": "Review claim for policy compliance and receipts",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "D1",
      "name": "Check if claim is over-limit or exceeds ₹50,000",
      "role": "System",
      "type": "decision"
    },
    {
      "step_id": "A2",
      "name": "Approve claim",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "A3",
      "name": "Approve claim with justification and escalate to Lead",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "A4",
      "name": "Approve claim after Lead validation",
      "role": "Lead",
      "type": "approval"
    },
    {
      "step_id": "R1",
      "name": "Correct claim based on rejection reason and resubmit",
      "role": "Executor",
      "type": "rework"
    },
    {
      "step_id": "A5",
      "name": "Approve corrected claim",
      "role": "Incharge",
      "type": "approval"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always"
    },
    {
      "stage": "Lead",
      "condition": "if claim is over-limit or exceeds ₹50,000"
    },
    {
      "stage": "HOD",
      "condition": "not mentioned in the document"
    }
  ],
  "dependencies": [],
  "rework_reasons": [
    "Required document missing",
    "Amount mismatch",
    "Wrong quantity",
    "Incorrect category"
  ],
  "first_pass_yield_target": 0.95
}
